typedef float vm_num_t;

struct vector3d
{
  float x, y, z;
};

class vm_stack
{
public:
  int salloc;
  char* buffer;
  char* SP;
  void* my_thread;

  char* get_SP() const { return SP; }
  void pop(int n) { SP -= n; }
  bool push(const char* src, int n);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };

  protected:
    char* name;

  public:
    function(const char* n);
    virtual ~function();
    virtual bool operator()(vm_stack& stack, entry_t entry) { return true; }
  };
};

class terrain
{
public:
  vm_num_t get_elevation(const vector3d& p, vector3d& normal,
                         void* default_region = 0,
                         unsigned char* hit_surface_type = 0);
};

class world_dynamics_system
{
  char padding[0xec];
  terrain* the_terrain;

public:
  terrain& get_the_terrain() { return *the_terrain; }
};

extern world_dynamics_system* g_world_ptr;
extern void error(const char*);

class slf_get_elevation_t : public script_library_class::function
{
public:
  slf_get_elevation_t(const char* n): script_library_class::function(n) { }

  struct parms_t
  {
    vector3d loc;
  };

  virtual bool operator()(vm_stack &stack, entry_t entry)
  {
    stack.pop(sizeof(parms_t));
    parms_t* parms = (parms_t*)stack.get_SP();
    vector3d dummy;
    vm_num_t result = g_world_ptr->get_the_terrain().get_elevation(parms->loc, dummy);
    if (!stack.push((char*)&result,sizeof(result)) )
      error("script stack overflow");
    return true;
  }
};

slf_get_elevation_t slf_get_elevation("get_elevation(vector3d)");
